SELECT
A.PLEDGE_AMT, (A.PLEDGE_RATIO * 100) pledgeRatio, (A.PLEDGE_FACE_VALUE * A.PLEDGE_NUMBER) pledgeFaceValue, C.TYPE_4, C.TYPE_5, B.finprod_type2, D.FINPROD_MARKET_ID, D.FINPROD_ABBR finprodAbbr, D.REGIST_ORG, (CASE WHEN E.PARTY_TYPE2 = '01' THEN '国有企业' WHEN '02' THEN '集体企业' WHEN '03' THEN '民营企业' WHEN '04' THEN '外资企业' WHEN '05' THEN '公众企业' WHEN '99' THEN '其他企业' END) companyNature, (CASE WHEN F.IS_SEC_BOND = 'Y' THEN '次级债' ELSE null END) isSecBond, G.PORTFOLIO_ID counterId, (H.INT_RATE * 100) intRate, H.TERM, H.VDATE, H.MDATE, ( select (CASE WHEN I.GRADE_RESULT = '01' THEN 'AAA+' WHEN '02' THEN 'AAA' WHEN '03' THEN 'AAA-' WHEN '04' THEN 'AA+' WHEN '05' THEN 'AA' WHEN '06' THEN 'AA-' WHEN '07' THEN 'A+' WHEN '08' THEN 'A' WHEN '09' THEN 'A-' WHEN '10' THEN 'A-1' WHEN '11' THEN 'A-2' WHEN '12' THEN 'A-3' WHEN '13' THEN 'BBB+' WHEN '14' THEN 'BBB' WHEN '15' THEN 'BBB-' WHEN '16' THEN 'BB+' WHEN '17' THEN 'BB' WHEN '18' THEN 'BB-' WHEN '19' THEN 'B+' WHEN '20' THEN 'B' WHEN '21' THEN 'B-' WHEN '22' THEN 'CCC+' WHEN '23' THEN 'CCC' WHEN '24' THEN 'CCC-' WHEN '25' THEN 'CC+' WHEN'26' THEN 'CC' WHEN '27' THEN 'CC-' WHEN '28' THEN 'C+' WHEN '29' THEN 'C' WHEN '30' THEN 'C-' WHEN '31' THEN 'D' ELSE '' END)
from MST_BOND_CREDIT_RATING I where I.O_TYPE='01' and I.O_CODE= D.FINPROD_MARKET_ID and I.GRADE_DATE <= str_to_date(#{sysDate},'%Y-%m-%d')
and I.GRADE_DATE =( select max(a.GRADE_DATE) from MST_BOND_CREDIT_RATING a where a.O_TYPE='01' and a.O_CODE= I.O_CODE and a.GRADE_DATE <= STR_TO_DATE(#{sysDate},'%Y-%m-%d')
) and I.GRADE_RESULT = ( select max(GRADE_RESULT) from MST_BOND_CREDIT_RATING where O_TYPE='01' and O_CODE= I.O_CODE and GRADE_DATE = I.GRADE_DATE )
) GRADE_RESULT FROM FIN_DEAL_PLEDGE A LEFT JOIN TRD_PRODUCT_DEAL B ON A.FINPROD_ID = B.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE C ON A.PLEDGE_FINPROD_ID = C.FINPROD_ID LEFT JOIN FIN_PRODUCT D ON A.PLEDGE_FINPROD_ID = D.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO_ADD E ON E.CUSTOMER_ID = D.ISSUER LEFT JOIN FIN_PRODUCT_ADD F ON A.PLEDGE_FINPROD_ID = F.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD G ON G.TRADE_ID = B.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD fpa ON G.PORTFOLIO_ID=fpa.PORTFOLIO_ID
LEFT JOIN FIN_TRADE_PRODUCT H ON A.FINPROD_ID = H.FINPROD_ID
LEFT JOIN PA_TRD_PRODUCT_DEAL J ON J.TRADE_ID = B.TRADE_ID WHERE 1 = 1 AND B.TRADE_STATUS='01'AND B.IS_CANCEL='N' AND J.BACK_LEND_DIRECTION in (#{BACK_LEND_DIRECTION_05},#{BACK_LEND_DIRECTION_06})
AND (H.VDATE <= STR_TO_DATE(#{sysDate},'%Y-%m-%d') AND STR_TO_DATE(#{sysDate},'%Y-%m-%d') < H.MDATE)
#{counterId,jdbcType=VARCHAR}
