AND C.TYPE_4 = #{type4}
AND C.TYPE_5 = #{type5}

SELECT fpd.TRADE_ID businessCode, tpd.BUSI_TYPE tradeType, tpd.TRADE_ID sourceBusinessCode, tpda.ENTRUST_ID entrustCode, pp.PORTFOLIO_ID portfolioId, pp.portfolio_name portfolioName, fp.finprod_market_id finprodId, fp.finprod_abbr finprodName, ptpd.back_lend_direction tradePs, tpd.share_amt tradeAmt, ftp.TRADE_MARKET tradeMarket, tpd.TRADE_DATE tradeDate, tpd.vdate vPayDate, tpd.mdate mPayDate, ftp.TERM_TYPE termType, tpd.mdate-tpd.vdate actCapDays, fpd.trade_date pledgeSubstitutionDate, tpd.CCY ccy, tpd.REMARK remark FROM TRD_PRODUCT_DEAL tpd LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpda.TRADE_ID = tpd.TRADE_ID LEFT JOIN PTL_TRADE PT ON tpd.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO pp ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN FIN_TRADE_PRODUCT ftp ON ((tpd.TRADE_STATUS = '01' AND ftp.FINPROD_ID = tpd.TRADE_ID)) LEFT JOIN FIN_PLEDGE_DISPLACE fpd ON tpd.trade_id=fpd.f_trade_id LEFT JOIN FIN_PLEDGE_DISPLACE_RESULT fpdr ON fpd.trade_id=fpdr.trade_id LEFT JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = tpd.TRADE_ID LEFT JOIN FIN_DEAL_TARGET fdt on tpd.TRADE_ID = fdt.FINPROD_ID LEFT JOIN FIN_PRODUCT fp ON fp.finprod_id =fdt.pledge_finprod_id WHERE pp.INVEST_YESORNO = 'Y' and fpd.trade_id is not null
#{portfolioId,jdbcType=VARCHAR}
AND ( tpd.TRADE_DATE <= STR_TO_DATE(#{substitutionTradeEndDate},'%Y-%m-%d') AND STR_TO_DATE(#{substitutionTradeStartDate},'%Y-%m-%d') <= tpd.TRADE_DATE)
AND ( fpd.TRADE_DATE <= STR_TO_DATE(#{substitutionEndDate},'%Y-%m-%d') AND STR_TO_DATE(#{substitutionStartDate},'%Y-%m-%d') <= fpd.TRADE_DATE)
AND ptpd.back_lend_direction=#{tradePs,jdbcType=VARCHAR}
AND tpd.BUSI_TYPE=#{tradeType,jdbcType=VARCHAR}
GROUP BY fpd.TRADE_ID,tpd.BUSI_TYPE,tpd.TRADE_ID,tpda.ENTRUST_ID,pp.PORTFOLIO_ID,pp.portfolio_name, fp.finprod_market_id,fp.finprod_abbr,ptpd.back_lend_direction,tpd.share_amt,ftp.TRADE_MARKET,tpd.TRADE_DATE, tpd.vdate,tpd.mdate,ftp.TERM_TYPE,ftp.act_cap_days,fpd.trade_date,tpd.CCY,tpd.REMARK ORDER BY fpd.TRADE_DATE DESC
